Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-singlenumberiii":{"key":"topic-singlenumberiii","number":null,"title":"Single Number III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Single Number III.py","code":"class Solution:\n    def singleNumber(self, nums: List[int]) -> List[int]:\n        xor = 0\n        for num in nums:\n            xor ^= num\n        def checkBit(num, i):\n            return (num >> i) & 1 == 1\n        pos = -1\n        for i in range(32):\n            if checkBit(xor, i):\n                pos = i\n                break\n        s1, s2 = 0, 0\n        for num in nums:\n            if checkBit(num, pos):\n                s1 ^= num\n            else:\n                s2 ^= num\n        return [s1, s2]","hash":"1e1742235bb887a66fe6380329b49def378517c377e7c0081544ebd5edf0321f","origins":[{"source":"solutions","path":"Single Number III.py"}]}],"sources":["solutions"]},"topic-singlerowkeyboard":{"key":"topic-singlerowkeyboard","number":null,"title":"Single Row Keyboard","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Single-Row Keyboard.py","code":"class Solution:\n    def calculateTime(self, keyboard: str, word: str) -> int:\n        indexMap, result, prevIndex = {}, 0, 0\n        for index, char in enumerate(keyboard):\n            indexMap[char] = index\n        for char in word:\n            result += abs(indexMap[char] - prevIndex)\n            prevIndex = indexMap[char]\n        return result","hash":"8200d414e9751813a056cf009b78cd4c603553eacf700542ee2a0050e699886e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Single-Row Keyboard.py"}]}],"sources":["solutions"]},"topic-singlethreadedcpu":{"key":"topic-singlethreadedcpu","number":null,"title":"Single Threaded CPU","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Single-Threaded CPU.py","code":"class Solution:\n    def getOrder(self, tasks: List[List[int]]) -> List[int]:\n        modifiedTasks = deque(sorted([(enqueueTime, processingTime, index) for index, (enqueueTime, processingTime) in enumerate(tasks)]))\n        result, heap, time = [], [], modifiedTasks[0][0]\n        while len(modifiedTasks) > 0 or len(heap) > 0:\n            while modifiedTasks and time >= modifiedTasks[0][0]:\n                task = modifiedTasks.popleft()\n                heapq.heappush(heap, (task[1], task[2]))\n            if heap:\n                task = heapq.heappop(heap)\n                result.append(task[1])\n                time = time + task[0]\n            else:\n                time = modifiedTasks[0][0]\n        return result","hash":"bb4ada2b378e846c38cd1c6090b2a1781f445892ba014505bb27c97c4535f9d6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Single-Threaded CPU.py"}]}],"sources":["solutions"]},"topic-slidingwindowmedian":{"key":"topic-slidingwindowmedian","number":null,"title":"Sliding Window Median","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sliding Window Median.py","code":"from sortedcontainers import SortedList\n\nclass Solution:\n    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:\n        def getMedian(stream):\n            midIndex = k // 2\n            if k % 2 == 0:\n                return (stream[midIndex] + stream[midIndex - 1]) / 2\n            else:\n                return stream[midIndex]\n        stream, n = SortedList(nums[:k]), len(nums)\n        result = [getMedian(stream),]\n        for i in range(k, n):\n            stream.discard(nums[i - k])\n            stream.add(nums[i])\n            result.append(getMedian(stream))\n        return result","hash":"d488e29fa0381115328fd121c42ea4845ed151cbf71b50c71342ebe4f5468142","origins":[{"source":"solutions","path":"Sliding Window Median.py"}]}],"sources":["solutions"]},"topic-slowestkey":{"key":"topic-slowestkey","number":null,"title":"Slowest Key","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Slowest Key.py","code":"class Solution:\n    def slowestKey(self, releaseTimes: List[int], keysPressed: str) -> str:\n        slowestKey, maximumTime = keysPressed[0], releaseTimes[0]\n        for i in range(1, len(releaseTimes)):\n            keyPressTime = releaseTimes[i] - releaseTimes[i - 1]\n            if keyPressTime > maximumTime or (keyPressTime == maximumTime and keysPressed[i] > slowestKey):\n                maximumTime = keyPressTime\n                slowestKey = keysPressed[i]\n        return slowestKey","hash":"66e298c2d46e94404d19d78824fd9c886b71b6f1ff3cdffbe651b9b5314b0a39","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-09 Leetcoding Challenge/Slowest Key.py"}]},{"language":"python","name":"Slowest Key.py","code":"class Solution:\n    def slowestKey(self, releaseTimes: List[int], keysPressed: str) -> str:\n        maxTime, maxTimeChar = releaseTimes[0], keysPressed[0]\n        for i in range(1, len(releaseTimes)):\n            releaseTime = releaseTimes[i] - releaseTimes[i - 1]\n            if releaseTime > maxTime:\n                maxTime, maxTimeChar = releaseTime, keysPressed[i]\n            elif releaseTime == maxTime:\n                if maxTimeChar < keysPressed[i]:\n                    maxTimeChar = keysPressed[i]\n        return maxTimeChar","hash":"1cf274ad2c4d060b79db7ae16a5e5b086d9ef6b4520ad96f18b10f05b0f172cd","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 212/Slowest Key.py"}]}],"sources":["solutions"]},"topic-smallestintegerdivisiblebyk":{"key":"topic-smallestintegerdivisiblebyk","number":null,"title":"Smallest Integer Divisible by K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest Integer Divisible by K.py","code":"class Solution(object):\n    def smallestRepunitDivByK(self, K):\n        \"\"\"\n        :type K: int\n        :rtype: int\n        \"\"\"\n        remainder = 0\n        for NLength in range(1, K + 1):\n            remainder = (remainder * 10 + 1) % K\n            if remainder == 0:\n                return NLength\n        return -1","hash":"ca8ec982dedc5cfdfd107e46ea02bf5a3480e455dc605551a86c1464e95a123f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Smallest Integer Divisible by K.py"}]}],"sources":["solutions"]},"topic-smallestnumberininfiniteset":{"key":"topic-smallestnumberininfiniteset","number":null,"title":"Smallest Number in Infinite Set","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest Number in Infinite Set.py","code":"class SmallestInfiniteSet:\n\n    def __init__(self):\n        self.smallest = 1\n        self.heap = [self.smallest,]\n        self.hashSet = set([self.smallest,])\n\n    def popSmallest(self) -> int:\n        num = heapq.heappop(self.heap)\n        self.hashSet.remove(num)\n        self.smallest += 1\n        self.addBack(self.smallest)\n        return num\n\n    def addBack(self, num: int) -> None:\n        if num not in self.hashSet:\n            heapq.heappush(self.heap, num)\n        self.hashSet.add(num)\n\n\n# Your SmallestInfiniteSet object will be instantiated and called as such:\n# obj = SmallestInfiniteSet()\n# param_1 = obj.popSmallest()\n# obj.addBack(num)","hash":"85bd6ab64f2b2f3b555e754600a7248eea91b48093f41ad91b0d96ffec298635","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Smallest Number in Infinite Set.py"}]}],"sources":["solutions"]},"topic-smallestrangei":{"key":"topic-smallestrangei","number":null,"title":"Smallest Range I","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest Range I.py","code":"class Solution:\n    def smallestRangeI(self, A: List[int], K: int) -> int:\n        return max(0, max(A) - min(A) - 2 * K)","hash":"a1604af45697f221412aaf9316960dc5684afeade145d31ff351166f4d3ce979","origins":[{"source":"solutions","path":"Smallest Range I.py"}]}],"sources":["solutions"]},"topic-smalleststringstartingfromleaf":{"key":"topic-smalleststringstartingfromleaf","number":null,"title":"Smallest String Starting From Leaf","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest String Starting From Leaf.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def smallestFromLeaf(self, root: Optional[TreeNode]) -> str:\n        self.result = '~'\n        def dfs(node: Optional[TreeNode], currentChars):\n            if node:\n                currentChars.append(chr(node.val + ord('a')))\n                if not node.left and not node.right:\n                    self.result = min(self.result, ''.join(reversed(currentChars)))\n                else:\n                    dfs(node.left, currentChars)\n                    dfs(node.right, currentChars)\n                currentChars.pop()\n        dfs(root, [])\n        return self.result","hash":"2c2a9422bbe42c2f151464cccd36e1fb12bec800697ef203c09e549fc9a71cd2","origins":[{"source":"solutions","path":"Smallest String Starting From Leaf.py"}]}],"sources":["solutions"]},"topic-smalleststringwithagivennumericvalue":{"key":"topic-smalleststringwithagivennumericvalue","number":null,"title":"Smallest String With A Given Numeric Value","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest String With A Given Numeric Value.py","code":"class Solution:\n    def getSmallestString(self, n: int, k: int) -> str:\n        result = []\n        for i in range(n - 1, -1, -1):\n            toRemove = min(k - i, 26)\n            result.append(chr(toRemove + ord('a') - 1))\n            k -= toRemove\n        return ''.join(result[::-1])","hash":"78606f57f5e3fd54839470db22a6b14cd2d347ea0252f24873dcbb9ae3ca7e64","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Smallest String With A Given Numeric Value.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Smallest String With A Given Numeric Value.py"}]}],"sources":["solutions"]},"topic-smalleststringwithswaps":{"key":"topic-smalleststringwithswaps","number":null,"title":"Smallest String With Swaps","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest String With Swaps.py","code":"class Solution:\n    def union(self, a, b):\n        self.parent[self.find(a)] = self.find(b)\n    \n    def find(self, a):\n        if self.parent[a] != a:\n            self.parent[a] = self.find(self.parent[a])\n        return self.parent[a]\n        \n    def smallestStringWithSwaps(self, s: str, pairs: List[List[int]]) -> str:\n        # 1. Union-Find\n        self.parent = list(range(len(s)))\n        for a, b in pairs:\n            self.union(a, b)\n        # 2. Group\n        group = defaultdict(lambda : ([], []))\n        for i, c in enumerate(s):\n            parent = self.find(i)\n            group[parent][0].append(i)\n            group[parent][1].append(c)\n        # 3. Sorting\n        result = [''] * len(s)\n        for ids, chars in group.values():\n            ids.sort()\n            chars.sort()\n            for c, i in zip(chars, ids):\n                result[i] = c\n        return ''.join(result)","hash":"f5bff5c6ddea99789a5e6f26930aebce756cf178d298e5345d2a3249448a0120","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Smallest String With Swaps.py"}]}],"sources":["solutions"]},"topic-smallestsubsequenceofdistinctcharacters":{"key":"topic-smallestsubsequenceofdistinctcharacters","number":null,"title":"Smallest Subsequence of Distinct Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest Subsequence of Distinct Characters.py","code":"class Solution:\n    def smallestSubsequence(self, s: str) -> str:\n        stack, seen, lastOccurence = deque([]), set(), {char: index for index, char in enumerate(s)}\n        for index, char in enumerate(s):\n            if char not in seen:\n                while stack and char < stack[-1] and index < lastOccurence[stack[-1]]:\n                    seen.discard(stack.pop())\n                seen.add(char)\n                stack.append(char)\n        return ''.join(stack)","hash":"4b572b50fc4a005f07a9bd7776abd8bab9ef0426a0b0f7224f34b0baa38626e1","origins":[{"source":"solutions","path":"Smallest Subsequence of Distinct Characters.py"}]}],"sources":["solutions"]},"topic-smallestsubtreewithallthedeepestnodes":{"key":"topic-smallestsubtreewithallthedeepestnodes","number":null,"title":"Smallest Subtree with all the Deepest Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Smallest Subtree with all the Deepest Nodes.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def subtreeWithAllDeepest(self, root: TreeNode) -> TreeNode:\n        # Tag each node with it's depth.\n        depth = {None: -1}\n        def dfs(node, parent = None):\n            if node:\n                depth[node] = depth[parent] + 1\n                dfs(node.left, node)\n                dfs(node.right, node)\n        dfs(root)\n\n        max_depth = max(depth.values())\n\n        def answer(node):\n            # Return the answer for the subtree at node.\n            if not node or depth.get(node, None) == max_depth:\n                return node\n            L, R = answer(node.left), answer(node.right)\n            return node if L and R else L or R\n\n        return answer(root)","hash":"80ba3337aa3611dee1a4c37ff412688c865dc62e0ccfa48480a2042687015381","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/Smallest Subtree with all the Deepest Nodes.py"}]}],"sources":["solutions"]},"topic-sortarraybyincreasingfrequency":{"key":"topic-sortarraybyincreasingfrequency","number":null,"title":"Sort Array by Increasing Frequency","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort Array by Increasing Frequency.py","code":"class Solution:\n    def frequencySort(self, nums: List[int]) -> List[int]:\n        countMap = Counter(nums)\n        frequencyArray = [(freq, item) for item, freq in countMap.items()]\n        frequencyArray.sort(key = lambda x : (x[0], -x[1]))\n        result = []\n        for x in frequencyArray:\n            for _ in range(x[0]):\n                result.append(x[1])\n        return result","hash":"a3a2a61ec1141b2fb0b0db67b63ae4dc590f7e1cd2bb1c58682c89d7767acaa5","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 38/Sort Array by Increasing Frequency.py"}]}],"sources":["solutions"]},"topic-sortarraybyparity":{"key":"topic-sortarraybyparity","number":null,"title":"Sort Array By Parity","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort Array By Parity.py","code":"class Solution:\n    def sortArrayByParity(self, A: List[int]) -> List[int]:\n        i, j = 0, len(A) - 1\n        while i < j:\n            if A[i] % 2 > A[j] % 2:\n                A[i], A[j] = A[j], A[i]\n            if A[i] % 2 == 0:\n                i += 1\n            if A[j] % 2 == 1:\n                j -= 1\n        return A","hash":"c1d9c8f7efe2616ddcfd5f51aee686d00f50eb40d10d81b665f8ad25c8c81a1d","origins":[{"source":"solutions","path":"Arrays/Sort Array By Parity.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Sort Array By Parity.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Sort Array By Parity.py"}]}],"sources":["solutions"]},"topic-sortevenandoddindicesindependently":{"key":"topic-sortevenandoddindicesindependently","number":null,"title":"Sort Even and Odd Indices Independently","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort Even and Odd Indices Independently.py","code":"class Solution:\n    def sortEvenOdd(self, nums: List[int]) -> List[int]:\n        odd, even = [], []\n        for i, num in enumerate(nums):\n            if i % 2:\n                odd.append(num)\n            else:\n                even.append(num)\n        odd.sort(reverse=True)\n        even.sort()\n        result = [None] * len(nums)\n        for i, num in enumerate(even):\n            result[2 * i] = num\n        for i, num in enumerate(odd):\n            result[(2 * i) + 1] = num\n        return result","hash":"2c26347e7fa9769556abd5e119b2acb1422b8d62da429919f6a4e2a4ccc3f565","origins":[{"source":"solutions","path":"Sort Even and Odd Indices Independently.py"}]}],"sources":["solutions"]},"topic-sortintegersbythenumberof1bits":{"key":"topic-sortintegersbythenumberof1bits","number":null,"title":"Sort Integers by The Number of 1 Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort Integers by The Number of 1 Bits.py","code":"class Solution:\n    def sortByBits(self, arr: List[int]) -> List[int]:\n        arr.sort()\n        return sorted(arr, key = lambda x : bin(x)[2:].count('1'))","hash":"a2da369739f42ab043cbd5eb4fe0165a1bb6f9d0bac08ec2a71cb069743ea6b4","origins":[{"source":"solutions","path":"Sort Integers by The Number of 1 Bits.py"}]}],"sources":["solutions"]},"topic-sortitemsbygroupsrespectingdependencies":{"key":"topic-sortitemsbygroupsrespectingdependencies","number":null,"title":"Sort Items by Groups Respecting Dependencies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort Items by Groups Respecting Dependencies.py","code":"class Solution:\n    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:\n        groupSet = set(group)\n        validGroupIndex = [i for i in range(max(m, n)) if i not in groupSet]\n        for index, g in enumerate(group):\n            if g == -1:\n                group[index] = validGroupIndex[-1]\n                validGroupIndex.pop()\n        itemsGraph, groupGraph, itemsInDegree, groupInDegree = defaultdict(list), defaultdict(list), [0] * n, [0] * n\n        for index, node in enumerate(beforeItems):\n            for item in node:\n                itemsGraph[item].append(index)\n                itemsInDegree[index] += 1\n                if group[item] != group[index]:\n                    groupGraph[group[item]].append(group[index])\n                    groupInDegree[group[index]] += 1\n        \n        def topologicalSort(graph, inDegree):\n            queue = deque([node for node, degree in enumerate(inDegree) if degree == 0])\n            result = []\n            while queue:\n                node = queue.popleft()\n                result.append(node)\n                for neighbour in graph[node]:\n                    inDegree[neighbour] -= 1\n                    if inDegree[neighbour] == 0:\n                        queue.append(neighbour)\n            return [] if len(result) != len(graph) else result\n        \n        itemsOrder, groupOrder = topologicalSort(itemsGraph, itemsInDegree), topologicalSort(groupGraph, groupInDegree)\n        if itemsOrder == [] or groupOrder == []:\n            return []\n        itemsGroup = defaultdict(list)\n        for item in itemsOrder:\n            itemsGroup[group[item]].append(item)\n        result = []\n        for g in groupOrder:\n            result.extend(itemsGroup[g])\n        return result","hash":"5939fe226bf331b51377bb12359d88b032255859f521afda8c5752659459516d","origins":[{"source":"solutions","path":"Sort Items by Groups Respecting Dependencies.py"}]}],"sources":["solutions"]},"topic-sortlist":{"key":"topic-sortlist","number":null,"title":"Sort List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def sortList(self, head: ListNode) -> ListNode:\n        \n        def getMiddleNode(node):\n            slow = fast = node\n            while fast and fast.next and fast.next.next:\n                slow = slow.next\n                fast = fast.next.next\n            return slow\n        \n        def mergeLists(nodeA, nodeB):\n            if nodeA is None:\n                return nodeB\n            if nodeB is None:\n                return nodeA\n            newList = None\n            if nodeA.val <= nodeB.val:\n                newList = nodeA\n                newList.next = mergeLists(nodeA.next, nodeB)\n            else:\n                newList = nodeB\n                newList.next = mergeLists(nodeA, nodeB.next)\n            return newList\n        \n        def mergeSort(node):\n            if node is None or node.next is None:\n                return node\n            middleNode = getMiddleNode(node)\n            middleNodeNext = middleNode.next\n            middleNode.next = None\n            leftList = mergeSort(node)\n            rightList = mergeSort(middleNodeNext)\n            return mergeLists(leftList, rightList)\n        \n        return mergeSort(head)","hash":"cbb655ff7a729b1e4076c5b1d4a102e9399c964da4394dcc7424e8962159400b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Sort List.py"},{"source":"solutions","path":"Sort List.py"}]},{"language":"python","name":"Sort List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def sortList(self, head: Optional[ListNode]) -> Optional[ListNode]:\n        def getMiddleNode(node):\n            slow = fast = node\n            while fast and fast.next and fast.next.next:\n                slow = slow.next\n                fast = fast.next.next\n            return slow\n        \n        def mergeLists(nodeA, nodeB):\n            if nodeA is None:\n                return nodeB\n            if nodeB is None:\n                return nodeA\n            newList = None\n            if nodeA.val <= nodeB.val:\n                newList = nodeA\n                newList.next = mergeLists(nodeA.next, nodeB)\n            else:\n                newList = nodeB\n                newList.next = mergeLists(nodeA, nodeB.next)\n            return newList\n        \n        def mergeSort(node):\n            if node is None or node.next is None:\n                return node\n            middleNode = getMiddleNode(node)\n            middleNodeNext = middleNode.next\n            middleNode.next = None\n            leftList = mergeSort(node)\n            rightList = mergeSort(middleNodeNext)\n            return mergeLists(leftList, rightList)\n        \n        return mergeSort(head)","hash":"c3cc2d2fbffdd91d06ee16fc167e94c0798316f8af703c46a74012d617459615","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Sort List.py"}]}],"sources":["solutions"]},"topic-sortthepeople":{"key":"topic-sortthepeople","number":null,"title":"Sort the People","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sort the People.py","code":"class Solution:\n    def sortPeople(self, names: List[str], heights: List[int]) -> List[str]:\n        data = [(height, name) for height, name in zip(heights, names)]\n        data.sort(reverse = True)\n        return [name for _, name in data]","hash":"e9bff5de69a1d4a6d48d544ccdbd66d56610d269a9c204749c9508fa3a9e6d73","origins":[{"source":"solutions","path":"Sort the People.py"}]}],"sources":["solutions"]},"topic-sortingthesentence":{"key":"topic-sortingthesentence","number":null,"title":"Sorting the Sentence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sorting the Sentence.py","code":"class Solution:\n    def sortSentence(self, s: str) -> str:\n        words, wordMap, result = s.split(' '), defaultdict(str), []\n        for word in words:\n            wordMap[word[-1]] = word[:-1]\n        for index in sorted(wordMap.keys()):\n            result.append(wordMap[index])\n        return ' '.join(result)","hash":"2a6fb4229a87487be32dc7aa9af41564eaada00607ffcd54974ee41c67a8ffcd","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 52/Sorting the Sentence.py"}]}],"sources":["solutions"]},"topic-specialarraywithxelementsgreaterthanorequalx":{"key":"topic-specialarraywithxelementsgreaterthanorequalx","number":null,"title":"Special Array With X Elements Greater Than or Equal X","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Special Array With X Elements Greater Than or Equal X.py","code":"class Solution:\n    def specialArray(self, nums: List[int]) -> int:\n        for i in range(len(nums) + 1):\n            count = 0\n            for num in nums:\n                if num >= i:\n                    count += 1\n                if count > i:\n                    break\n            if count == i:\n                return i\n        return -1","hash":"749a70b8d5a2617016bfcb850bdbe0e6725a104f186909c97228da3d29222880","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 209/Special Array With X Elements Greater Than or Equal X.py"}]}],"sources":["solutions"]},"topic-specialpositionsinabinarymatrix":{"key":"topic-specialpositionsinabinarymatrix","number":null,"title":"Special Positions in a Binary Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Special Positions in a Binary Matrix.py","code":"class Solution:\n    def numSpecial(self, mat: List[List[int]]) -> int:\n        special, rows, cols = 0, len(mat), len(mat[0])\n        for row in range(rows):\n            countOfOneInRow = mat[row].count(1)\n            if countOfOneInRow == 1:\n                countOfOneInCol = 0\n                indexOfOne = mat[row].index(1)\n                for i in range(rows):\n                    if mat[i][indexOfOne] == 1:\n                        countOfOneInCol += 1\n                if countOfOneInCol == 1:\n                    special += 1\n        return special","hash":"92f00e165aa9b3706abfb56be8742975fc0deda72c72e1e960ef55bda277d261","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 206/Special Positions in a Binary Matrix.py"}]}],"sources":["solutions"]},"topic-splitastringinbalancedstrings":{"key":"topic-splitastringinbalancedstrings","number":null,"title":"Split a String in Balanced Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Split a String in Balanced Strings.py","code":"class Solution:\n    def balancedStringSplit(self, s: str) -> int:\n        frequency, result = 0, 0\n        for char in s:\n            frequency += 1 if char == 'L' else -1\n            if frequency == 0:\n                result += 1\n        return result","hash":"583b92e27605e56761a0cf72e0814eae0807338e3729d7d1510f3b82e3f64b9d","origins":[{"source":"solutions","path":"Split a String in Balanced Strings.py"}]}],"sources":["solutions"]},"topic-splitastringintothemaxnumberofuniquesubstrings":{"key":"topic-splitastringintothemaxnumberofuniquesubstrings","number":null,"title":"Split a String Into the Max Number of Unique Substrings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Split a String Into the Max Number of Unique Substrings.py","code":"class Solution:\n    def maxUniqueSplit(self, s: str) -> int:\n        seen, result, sLength = set(), 0, len(s)\n        def backtrack(start):\n            nonlocal result\n            if start == sLength:\n                return True\n            elif start > sLength:\n                return False\n            else:\n                for end in range(start + 1, sLength + 1):\n                    if s[start:end] not in seen:\n                        seen.add(s[start:end])\n                        temp = backtrack(end)\n                        if temp:\n                            result = max(result, len(seen))\n                        seen.remove(s[start:end])\n                return True\n        backtrack(0)\n        return result","hash":"4e945488e8f97f40c1d04f178ae0112dfdcb96898bb61e8c4bc710fddc4ed59b","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 207/Split a String Into the Max Number of Unique Substrings.py"}]}],"sources":["solutions"]},"topic-splitarraylargestsum":{"key":"topic-splitarraylargestsum","number":null,"title":"Split Array Largest Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Split Array Largest Sum.py","code":"class Solution:\n    def splitArray(self, nums: List[int], m: int) -> int:\n        left, right = max(nums), sum(nums)\n        def isFeasible(threshold):\n            total, count = 0, 1\n            for num in nums:\n                total += num\n                if total > threshold:\n                    count += 1\n                    total = num\n                    if count > m:\n                        return False\n            return True\n        while left < right:\n            mid = left + (right - left) // 2\n            if isFeasible(mid):\n                right = mid\n            else:\n                left = mid + 1\n        return left","hash":"819040f93d7e32d51513d009fdd05b04c5bf118d1a60f2ec0bf3af4eb7247eec","origins":[{"source":"solutions","path":"Google Interview Questions/Split Array Largest Sum.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Split Array Largest Sum.py"}]}],"sources":["solutions"]},"topic-splittwostringstomakepalindromeo1":{"key":"topic-splittwostringstomakepalindromeo1","number":null,"title":"Split Two Strings to Make Palindrome O(1)","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Split Two Strings to Make Palindrome - O(1).py","code":"class Solution:\n    def checkPalindromeFormation(self, a: str, b: str) -> bool:\n        if len(a) == 1:\n            return True\n        if a[:2] == b[-2:][::-1]:\n            return True\n        if a[-2:][::-1] == b[:2]:\n            return True\n        return False","hash":"3f7441c3ba617ded8578d8b268dce9b7c25155e71a0142e162080f5ccc567315","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 210/Split Two Strings to Make Palindrome - O(1).py"}]}],"sources":["solutions"]},"topic-splittwostringstomakepalindromeon":{"key":"topic-splittwostringstomakepalindromeon","number":null,"title":"Split Two Strings to Make Palindrome O(n)","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Split Two Strings to Make Palindrome - O(n).py","code":"class Solution:\n    def checkPalindromeFormation(self, a: str, b: str) -> bool:\n        def isPalindrome(string, startIndex, endIndex):\n            while endIndex - startIndex > 0:\n                if string[startIndex] != string[endIndex]:\n                    return False\n                startIndex += 1\n                endIndex -= 1\n            return True\n        \n        def areTwoStringsPalindrome(string1, string2):\n            startIndex, endIndex = 0, len(string1) - 1\n            while endIndex - startIndex > 0 and string1[startIndex] == string2[endIndex]:\n                startIndex += 1\n                endIndex -= 1\n            return isPalindrome(string1, startIndex, endIndex) or isPalindrome(string2, startIndex, endIndex)\n        \n        return areTwoStringsPalindrome(a, b) or areTwoStringsPalindrome(b, a)","hash":"fcb51edb5975ad74ffd6976995bfd1f67fd8054769edc12d24bb89a44dc09cc1","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 210/Split Two Strings to Make Palindrome - O(n).py"}]}],"sources":["solutions"]},"topic-squaresofasortedarray":{"key":"topic-squaresofasortedarray","number":null,"title":"Squares of a Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Squares of a Sorted Array.py","code":"class Solution:\n    def sortedSquares(self, nums: List[int]) -> List[int]:\n        return sorted([num * num for num in nums])","hash":"f710acfd3f744261811935fd09ed53899bf85168ea4995a7a66a8116b1a6d53b","origins":[{"source":"solutions","path":"Arrays/Squares of a Sorted Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/Squares of a Sorted Array.py"}]}],"sources":["solutions"]},"topic-squirrelsimulation":{"key":"topic-squirrelsimulation","number":null,"title":"Squirrel Simulation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Squirrel Simulation.py","code":"class Solution:\n    def minDistance(self, height: int, width: int, tree: List[int], squirrel: List[int], nuts: List[List[int]]) -> int:\n        def distance(a, b):\n            return abs(a[1] - b[1]) + abs(a[0] - b[0])\n        def distanceToTree(nut):\n            return distance(nut, tree)\n        def distanceToSquirrel(nut):\n            return distance(nut, squirrel)\n        totalDistance, maxSaving = 0, float('-inf')\n        for nut in nuts:\n            d = distanceToTree(nut)\n            totalDistance += (d * 2)\n            maxSaving = max(maxSaving, d - distanceToSquirrel(nut))\n        return totalDistance - maxSaving","hash":"8a95942319eca1b4a306eba2da655f3d3cc56788de51c518914b4b664f77339a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Squirrel Simulation.py"}]}],"sources":["solutions"]},"topic-stonegame":{"key":"topic-stonegame","number":null,"title":"Stone Game","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Stone Game.py","code":"class Solution:\n    def stoneGame(self, piles: List[int]) -> bool:\n        return True","hash":"cd4c35a781a41d78f399799a554c98fe117273ed0fc8edefc3d79b05d1bd876e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Stone Game.py"}]}],"sources":["solutions"]},"topic-stonegameiv":{"key":"topic-stonegameiv","number":null,"title":"Stone Game IV","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Stone Game IV.py","code":"class Solution:\n    def winnerSquareGame(self, n: int) -> bool:\n        @lru_cache(maxsize=None)\n        def dfs(remain):\n            if remain == 0:\n                return False\n            sqrtRoot = int(remain ** 0.5)\n            for i in range(sqrtRoot, 0, -1):\n                if not dfs(remain - i * i):\n                    return True\n            return False\n        return dfs(n)","hash":"51ee99c0584af94b6474f300f29f31b4726061bef8ea54b39a095c99481c3381","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Stone Game IV.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Stone Game IV.py"}]}],"sources":["solutions"]},"topic-stonegamev":{"key":"topic-stonegamev","number":null,"title":"Stone Game V","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Stone Game V.py","code":"class Solution:\n    def stoneGameV(self, stoneValue: List[int]) -> int:\n        n = len(stoneValue)\n        dp = [[-1] * (n + 1) for _ in range(n + 1)]\n        \n        @lru_cache(None)\n        def playGame(start, end):\n            if end - start <= 1:\n                return 0\n            if dp[start][end] == -1:\n                for mid in range(start + 1, end):\n                    leftSum = sum(stoneValue[start: mid])\n                    rightSum = sum(stoneValue[mid: end])\n                    if leftSum <= rightSum:\n                        dp[start][end] = max(dp[start][end], leftSum + playGame(start, mid))\n                    if leftSum >= rightSum:\n                        dp[start][end] = max(dp[start][end], rightSum + playGame(mid, end))\n            return dp[start][end]\n        \n        return playGame(0, n)","hash":"6305bf372df83980148d1bc132734ab3f8e9960e70f0ffac95a1cccbe0e28ab2","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 203/Stone Game V.py"}]}],"sources":["solutions"]},"topic-stonegamevii":{"key":"topic-stonegamevii","number":null,"title":"Stone Game VII","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Stone Game VII.py","code":"class Solution:\n    def stoneGameVII(self, stones: List[int]) -> int:\n        n = len(stones)\n        dp, prefixSum = [[0] * n for _ in range(n)], [0] * (n + 1)\n        for i in range(n):\n            prefixSum[i + 1] = prefixSum[i] + stones[i]\n        for length in range(2, n + 1):\n            for start in range(n + 1 - length):\n                end = start + length - 1\n                scoreRemoveFirst, scoreRemoveLast = prefixSum[end + 1] - prefixSum[start + 1], prefixSum[end] - prefixSum[start]\n                dp[start][end] = max(scoreRemoveFirst - dp[start + 1][end], scoreRemoveLast - dp[start][end - 1])\n        return dp[0][n - 1]","hash":"b0a4172e5f5180941645e38cf8f6d09738ecd2ed705a277fb19db4348aa9fb62","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-06 Leetcoding Challenge/Stone Game VII.py"}]}],"sources":["solutions"]},"topic-strangeprinterii":{"key":"topic-strangeprinterii","number":null,"title":"Strange Printer II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Strange Printer II.py","code":"class Solution:\n    def isPrintable(self, targetGrid: List[List[int]]) -> bool:\n        colors, rows, cols = set(), len(targetGrid), len(targetGrid[0])\n        for r in range(rows):\n            for c in range(cols):\n                colors.add(targetGrid[r][c])\n        colorPositions = [[float('inf'), float('inf'), float('-inf'), float('-inf')] for _ in range(max(colors) + 1)] # left, top, right, bottom\n        for r in range(rows):\n            for c in range(cols):\n                color = targetGrid[r][c]\n                colorPositions[color][0] = min(colorPositions[color][0], c)\n                colorPositions[color][1] = min(colorPositions[color][1], r)\n                colorPositions[color][2] = max(colorPositions[color][2], c)\n                colorPositions[color][3] = max(colorPositions[color][3], r)\n        \n        def isTopColor(color):\n            for r in range(colorPositions[color][1], colorPositions[color][3] + 1):\n                for c in range(colorPositions[color][0], colorPositions[color][2] + 1):\n                    if targetGrid[r][c] > 0 and targetGrid[r][c] != color:\n                        return False\n            for r in range(colorPositions[color][1], colorPositions[color][3] + 1):\n                for c in range(colorPositions[color][0], colorPositions[color][2] + 1):\n                    targetGrid[r][c] = 0\n            return True\n        \n        while colors:\n            nonTopColors = set()\n            for color in colors:\n                if not isTopColor(color):\n                    nonTopColors.add(color)\n            if len(colors) == len(nonTopColors):\n                return False\n            colors = nonTopColors\n        return True","hash":"25a30dc4c4415d3d819401b98853e6efdf1eb2348c33c2f2719d79a6b060b8fd","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 35/Strange Printer II.py"}]}],"sources":["solutions"]},"topic-streamofcharacters":{"key":"topic-streamofcharacters","number":null,"title":"Stream of Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Stream of Characters.py","code":"class StreamChecker:\n\n    def __init__(self, words: List[str]):\n        self.trie = {}\n        self.stream = deque()\n        for word in words:\n            node = self.trie\n            for ch in word[::-1]:\n                if ch not in node:\n                    node[ch] = {}\n                node = node[ch]\n            node['$'] = word\n\n    def query(self, letter: str) -> bool:\n        self.stream.appendleft(letter)\n        node = self.trie\n        for ch in self.stream:\n            if '$' in node:\n                return True\n            if ch not in node:\n                return False\n            node = node[ch]\n        return '$' in node\n\n\n# Your StreamChecker object will be instantiated and called as such:\n# obj = StreamChecker(words)\n# param_1 = obj.query(letter)","hash":"54c8e765e45dd4dd04cb57c4f5935834644287112e9d8ac269b02d2132807d08","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Stream of Characters.py"}]}],"sources":["solutions"]},"topic-stringtointegeratoi":{"key":"topic-stringtointegeratoi","number":null,"title":"String to Integer (atoi)","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"String to Integer (atoi).py","code":"class Solution:\n    def myAtoi(self, s: str) -> int:\n        sign, number, index, sLen = 1, 0, 0, len(s)\n        while index < sLen and s[index] == ' ':\n            index += 1\n        if index < sLen and (s[index] == '+' or s[index] == '-'):\n            sign = -1 if s[index] == '-' else 1\n            index += 1\n        while index < sLen and s[index].isdigit():\n            number = number * 10 + (ord(s[index]) - ord('0'))\n            index += 1\n        if (sign * number) > 2**31 - 1:\n            return 2**31 - 1\n        elif (sign * number) < -1 * (2**31):\n            return -1 * (2**31)\n        else:\n            return (sign * number)","hash":"b7d1e27678b6fda50c72ed690b88da6d31096e705d6e273df8d75723791f1751","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/String to Integer (atoi).py"},{"source":"solutions","path":"Microsoft Interview Questions/String to Integer (atoi).py"}]}],"sources":["solutions"]},"topic-studentsandexaminations":{"key":"topic-studentsandexaminations","number":null,"title":"Students and Examinations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Students and Examinations.sql","code":"# Write your MySQL query statement below\nSELECT stu.student_id, stu.student_name, sub.subject_name, COUNT(exam.subject_name) AS attended_exams\nFROM Students stu JOIN Subjects sub LEFT JOIN Examinations exam ON stu.student_id = exam.student_id AND sub.subject_name = exam.subject_name\nGROUP BY stu.student_id, sub.subject_name\nORDER BY stu.student_id, sub.subject_name;","hash":"2313eeac2161a82b19b2cc19234b3ccacfa0f7f288ee1c66767cff0903763db6","origins":[{"source":"solutions","path":"Students and Examinations.sql"}]}],"sources":["solutions"]},"topic-subarrayproductlessthank":{"key":"topic-subarrayproductlessthank","number":null,"title":"Subarray Product Less Than K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Subarray Product Less Than K.py","code":"class Solution:\n    def numSubarrayProductLessThanK(self, nums: List[int], k: int) -> int:\n        if k <= 1:\n            return 0\n        product, result, left = 1, 0, 0\n        for right, val in enumerate(nums):\n            product *= val\n            while product >= k:\n                product /= nums[left]\n                left += 1\n            result += right - left + 1\n        return result","hash":"9c6df790be86f100fe4228e631673a422b47ba11886217fcb47e7445fe56908a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Subarray Product Less Than K.py"}]}],"sources":["solutions"]},"topic-subarraysumequalsk":{"key":"topic-subarraysumequalsk","number":null,"title":"Subarray Sum Equals K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Subarray Sum Equals K.py","code":"class Solution:\n    def subarraySum(self, nums: List[int], k: int) -> int:\n        sumMap = defaultdict(int)\n        countOfSubArrays = 0\n        subArraySum = 0\n        sumMap[0] = 1\n        for n in nums:\n            subArraySum += n\n            if sumMap.get(subArraySum - k) is not None:\n                countOfSubArrays += sumMap.get(subArraySum - k)\n            sumMap[subArraySum] += 1\n        return countOfSubArrays","hash":"db5eead02283edbdd9f871d7ff902fdc8f9e4b2631c81982757d82bd9456e32c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Subarray Sum Equals K.py"},{"source":"solutions","path":"Subarray Sum Equals K.py"}]}],"sources":["solutions"]},"topic-subarraysumsdivisiblebyk":{"key":"topic-subarraysumsdivisiblebyk","number":null,"title":"Subarray Sums Divisible by K","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Subarray Sums Divisible by K.py","code":"class Solution:\n    def subarraysDivByK(self, nums: List[int], k: int) -> int:\n        prefixMod, result = 0, 0\n        modGroups = defaultdict(int)\n        modGroups[0] = 1\n        for num in nums:\n            # Take modulo twice to avoid negative remainders.\n            prefixMod = (prefixMod + (num % k) + k) % k\n            # Add the count of subarrays that have the same remainder as the current\n            # one to cancel out the remainders.\n            result += modGroups[prefixMod]\n            modGroups[prefixMod] += 1\n        return result","hash":"6014bf12eac4c0239729d15b2e30d0b7514421834d20b79f009ec2f5fee02ee5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Subarray Sums Divisible by K.py"}]}],"sources":["solutions"]},"topic-substringsofsizethreewithdistinctcharacters":{"key":"topic-substringsofsizethreewithdistinctcharacters","number":null,"title":"Substrings of Size Three with Distinct Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Substrings of Size Three with Distinct Characters.py","code":"class Solution:\n    def countGoodSubstrings(self, s: str) -> int:\n        result = 0\n        for i in range(len(s) - 2):\n            if len(set(s[i:i+3])) == 3:\n                result += 1\n        return result","hash":"ffe5e464d61d6d7d303d84241ab10f44ba21a3d5996b6813424492474cc181cb","origins":[{"source":"solutions","path":"Substrings of Size Three with Distinct Characters.py"}]}],"sources":["solutions"]},"topic-subtracttheproductandsumofdigitsofaninteger":{"key":"topic-subtracttheproductandsumofdigitsofaninteger","number":null,"title":"Subtract the Product and Sum of Digits of an Integer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Subtract the Product and Sum of Digits of an Integer.py","code":"class Solution:\n    def subtractProductAndSum(self, n: int) -> int:\n        product, currentSum = 1, 0\n        while n > 0:\n            n, d = divmod(n, 10)\n            product *= d\n            currentSum += d\n        return product - currentSum","hash":"70282777dc1a53d3c63315647b373c7deae59ddd0e8e6c3163fa0135d0707363","origins":[{"source":"solutions","path":"Subtract the Product and Sum of Digits of an Integer.py"}]}],"sources":["solutions"]},"topic-subtreeofanothertree":{"key":"topic-subtreeofanothertree","number":null,"title":"Subtree of Another Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Subtree of Another Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isSubtree(self, s: TreeNode, t: TreeNode) -> bool:\n        def isIdentical(s, t):\n            if s is None and t is None:\n                return True\n            elif s is not None and t is not None:\n                return s.val == t.val and isIdentical(s.left, t.left) and isIdentical(s.right, t.right)\n            else:\n                return False\n        def preorder(node):\n            nonlocal t\n            if node:\n                if node.val == t.val:\n                    if isIdentical(node, t):\n                        return True\n                l = preorder(node.left)\n                r = preorder(node.right)\n                return l or r\n            return t is None\n        return preorder(s)","hash":"61b399a28b83061ffc27840b9e8c762b696932743769cd96346993e683775dca","origins":[{"source":"solutions","path":"Subtree of Another Tree.py"}]}],"sources":["solutions"]},"topic-successfulpairsofspellsandpotions":{"key":"topic-successfulpairsofspellsandpotions","number":null,"title":"Successful Pairs of Spells and Potions","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Successful Pairs of Spells and Potions.py","code":"class Solution:\n    def successfulPairs(self, spells: List[int], potions: List[int], success: int) -> List[int]:\n        potions.sort()\n        result = []\n        n = len(potions)\n        maxPotion = potions[n - 1]\n        for spell in spells:\n            minPotion = (success + spell - 1) // spell\n            if minPotion > maxPotion:\n                result.append(0)\n                continue\n            index = bisect.bisect_left(potions, minPotion)\n            result.append(n - index)\n        return result","hash":"f04c1f042809c7b4c07e54f890c94cc91a4d3f3452f300aa4a2752458b59ba26","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Successful Pairs of Spells and Potions.py"}]}],"sources":["solutions"]},"topic-sumofalloddlengthsubarrays":{"key":"topic-sumofalloddlengthsubarrays","number":null,"title":"Sum of All Odd Length Subarrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of All Odd Length Subarrays.py","code":"class Solution:\n    def sumOddLengthSubarrays(self, arr: List[int]) -> int:\n        length, result = 1, 0\n        while length <= len(arr):\n            for start in range(len(arr) - length + 1):\n                result += sum(arr[start : start + length])\n            length += 2\n        return result","hash":"77b0c07f3045c6306431283604ed8675e10d5f8406234fe70ee030b28486ed52","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 35/Sum of All Odd Length Subarrays.py"}]}],"sources":["solutions"]},"topic-sumofdigitsintheminimumnumber":{"key":"topic-sumofdigitsintheminimumnumber","number":null,"title":"Sum of Digits in the Minimum Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Digits in the Minimum Number.py","code":"class Solution:\n    def sumOfDigits(self, A: List[int]) -> int:\n        return 0 if sum([int(digit) for digit in str(min(A))]) % 2 else 1","hash":"5f8347b901c2065aa552b7a5d1b99bdb9cbc59e4fd1c710422933196101fe29b","origins":[{"source":"solutions","path":"Sum of Digits in the Minimum Number.py"}]}],"sources":["solutions"]},"topic-sumofdigitsofstringafterconvert":{"key":"topic-sumofdigitsofstringafterconvert","number":null,"title":"Sum of Digits of String After Convert","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Digits of String After Convert.py","code":"class Solution:\n    def getLucky(self, s: str, k: int) -> int:\n        transform = ''.join([str(ord(c) - ord('a') + 1) for c in s])\n        for itr in range(k):\n            transform = str(sum([int(i) for i in transform]))\n        return int(transform)","hash":"2154db0664558be257d5068f0160d7115a84016178209b54a6ac3c1548ab8d56","origins":[{"source":"solutions","path":"Sum of Digits of String After Convert.py"}]}],"sources":["solutions"]},"topic-sumofdistancesintree":{"key":"topic-sumofdistancesintree","number":null,"title":"Sum of Distances in Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Distances in Tree.py","code":"class Solution:\n    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:\n        graph = defaultdict(set)\n        for u, v in edges:\n            graph[u].add(v)\n            graph[v].add(u)\n        count = [1] * n\n        ans = [0] * n\n        def postorder(node = 0, parent = None):\n            for child in graph[node]:\n                if child != parent:\n                    postorder(child, node)\n                    count[node] += count[child]\n                    ans[node] += ans[child] + count[child]\n        def preorder(node = 0, parent = None):\n            for child in graph[node]:\n                if child != parent:\n                    ans[child] = ans[node] - (2 * count[child]) + n\n                    preorder(child, node)\n        postorder()\n        preorder()\n        return ans","hash":"82e2a81fd6da7652a967c633afa1817d12fe5da9b1054a874ae0ecfcdd8933ce","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Sum of Distances in Tree.py"},{"source":"solutions","path":"Sum of Distances in Tree.py"}]}],"sources":["solutions"]},"topic-sumofflooredpairs":{"key":"topic-sumofflooredpairs","number":null,"title":"Sum of Floored Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Floored Pairs.py","code":"class Solution:\n    def sumOfFlooredPairs(self, nums: List[int]) -> int:\n        MOD, freqMap, maximumElement, result = 10**9 + 7, Counter(nums), max(nums), 0\n        prefixFreq = [0] * (maximumElement + 1)\n        for num in range(1, maximumElement + 1):\n            prefixFreq[num] = prefixFreq[num - 1] + freqMap[num]\n        for num in freqMap.keys():\n            for i in range(num, maximumElement + 1, num):\n                result = (result + freqMap[num] * (prefixFreq[-1] - prefixFreq[i - 1])) % MOD\n        return result % MOD","hash":"0e7a2569c51f6b756d1718c9ede184a00ecc55c4e45cba7dc73d8dc04ed82cfb","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 52/Sum of Floored Pairs.py"}]}],"sources":["solutions"]},"topic-sumofleftleaves":{"key":"topic-sumofleftleaves","number":null,"title":"Sum of Left Leaves","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Left Leaves.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumOfLeftLeaves(self, root: TreeNode) -> int:\n        def isLeaf(node):\n            return node is not None and node.left is None and node.right is None\n        if root is None:\n            return 0\n        stack = deque([root,])\n        total = 0\n        while stack:\n            node = stack.pop()\n            if isLeaf(node.left):\n                total += node.left.val\n            if node.right is not None:\n                stack.append(node.right)\n            if node.left is not None:\n                stack.append(node.left)\n        return total","hash":"22f9a44ee77634948c0ced9161681a37794ccd0c2db9bf3224cd917c66086f4a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Sum of Left Leaves.py"}]}],"sources":["solutions"]},"topic-sumofroottoleafbinarynumber":{"key":"topic-sumofroottoleafbinarynumber","number":null,"title":"Sum of Root To Leaf Binary Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Root To Leaf Binary Number.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumRootToLeaf(self, root: Optional[TreeNode]) -> int:\n        def preOrder(node, currentSum):\n            nonlocal rootToLeafSum\n            if node:\n                currentSum = currentSum * 2 + node.val\n                if node.left is None and node.right is None:\n                    rootToLeafSum += currentSum\n                else:\n                    preOrder(node.left, currentSum)\n                    preOrder(node.right, currentSum)\n        rootToLeafSum = 0\n        preOrder(root, 0)\n        return rootToLeafSum","hash":"02510f84dcf63937bc8acf19f79b410ec05f85ed6de794be2c6be6ef0b1f01fb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Sum of Root To Leaf Binary Number.py"}]}],"sources":["solutions"]},"topic-sumofroottoleafbinarynumbers":{"key":"topic-sumofroottoleafbinarynumbers","number":null,"title":"Sum of Root To Leaf Binary Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Root To Leaf Binary Numbers.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumRootToLeaf(self, root: TreeNode) -> int:\n        self.sum = 0\n        \n        def sumPath(node, binaryString):\n            if node is None:\n                return\n            if node.left is None and node.right is None:\n                self.sum += int(binaryString + str(node.val), base=2)\n                return\n            if node.left:\n                sumPath(node.left, binaryString + str(node.val))\n            if node.right:\n                sumPath(node.right, binaryString + str(node.val))\n        \n        sumPath(root, '')\n        return self.sum","hash":"cb55b52fd0afa2b13f660b637a9a82ce842936807154a3b50d77955bf88d7629","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Sum of Root To Leaf Binary Numbers.py"}]}],"sources":["solutions"]},"topic-sumofsquarenumbers":{"key":"topic-sumofsquarenumbers","number":null,"title":"Sum of Square Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Square Numbers.py","code":"class Solution:\n    def judgeSquareSum(self, c: int) -> bool:\n        a = 0\n        while a * a <= c:\n            b = math.sqrt(c - int(a * a))\n            if b == int(b):\n                return True\n            a += 1\n        return False","hash":"b4b584128275c67972208a4bf48616f10ee626f1e87e3e7e3a0726a2a9ecce40","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Sum of Square Numbers.py"},{"source":"solutions","path":"Sum of Square Numbers.py"}]}],"sources":["solutions"]},"topic-sumoftwointegers":{"key":"topic-sumoftwointegers","number":null,"title":"Sum of Two Integers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Two Integers.py","code":"class Solution:\n    def getSum(self, a: int, b: int) -> int:\n        x, y = abs(a), abs(b)\n        if x < y:\n            return self.getSum(b, a)\n        sign = 1 if a > 0 else -1\n        if a * b >= 0:\n            while y:\n                x, y = x ^ y, (x & y) << 1\n        else:\n            while y:\n                x, y = x ^ y, ((~x) & y) << 1\n        return x * sign","hash":"5300d282551c56c92c4e6f577586be5ec614ca11f2f466ae900e90ed63b990f4","origins":[{"source":"solutions","path":"Sum of Two Integers.py"}]}],"sources":["solutions"]},"topic-sumofuniqueelements":{"key":"topic-sumofuniqueelements","number":null,"title":"Sum of Unique Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum of Unique Elements.py","code":"class Solution:\n    def sumOfUnique(self, nums: List[int]) -> int:\n        freqMap = Counter(nums)\n        result = 0\n        for key, value in freqMap.items():\n            if value == 1:\n                result += key\n        return result","hash":"3082ef394604e840bb0378c5db5ff066fd8f310fa7115f9243c99019e684df28","origins":[{"source":"solutions","path":"Sum of Unique Elements.py"}]}],"sources":["solutions"]},"topic-sumroottoleafnumbers":{"key":"topic-sumroottoleafnumbers","number":null,"title":"Sum Root to Leaf Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum Root to Leaf Numbers.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumNumbers(self, root: TreeNode) -> int:\n        def preOrder(node, currentNumber):\n            nonlocal rootToLeafSum\n            if node is not None:\n                currentNumber = currentNumber * 10 + node.val\n                if node.left is None and node.right is None:\n                    rootToLeafSum += currentNumber\n                else:\n                    preOrder(node.left, currentNumber)\n                    preOrder(node.right, currentNumber)\n        rootToLeafSum = 0\n        preOrder(root, 0)\n        return rootToLeafSum","hash":"a7859c6cff35e3f0c179691422972379be7100009a5e78d1be9287b447f373f1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Sum Root to Leaf Numbers.py"}]}],"sources":["solutions"]},"topic-sumroottoleafnumbersiterative":{"key":"topic-sumroottoleafnumbersiterative","number":null,"title":"Sum Root to Leaf Numbers Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum Root to Leaf Numbers - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumNumbers(self, root: TreeNode) -> int:\n        rootToLeafSum = 0\n        stack = [(root, 0)]\n        while len(stack) != 0:\n            node, currentNumber = stack.pop()\n            if node is not None:\n                currentNumber = currentNumber * 10 + node.val\n                if node.left is None and node.right is None:\n                    rootToLeafSum += currentNumber\n                else:\n                    stack.append((node.left, currentNumber))\n                    stack.append((node.right, currentNumber))\n        return rootToLeafSum","hash":"d09d5daab1f6a84fc6254119b80280142e9a4c1538483f3cd01e892031c6810a","origins":[{"source":"solutions","path":"Sum Root to Leaf Numbers - Iterative.py"}]}],"sources":["solutions"]},"topic-sumroottoleafnumbersrecursive":{"key":"topic-sumroottoleafnumbersrecursive","number":null,"title":"Sum Root to Leaf Numbers Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Sum Root to Leaf Numbers - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def sumNumbers(self, root: TreeNode) -> int:\n        def preOrder(node, currentNumber):\n            nonlocal rootToLeafSum\n            if node is not None:\n                currentNumber = currentNumber * 10 + node.val\n                if node.left is None and node.right is None:\n                    rootToLeafSum += currentNumber\n                else:\n                    preOrder(node.left, currentNumber)\n                    preOrder(node.right, currentNumber)\n        rootToLeafSum = 0\n        preOrder(root, 0)\n        return rootToLeafSum","hash":"a7859c6cff35e3f0c179691422972379be7100009a5e78d1be9287b447f373f1","origins":[{"source":"solutions","path":"Sum Root to Leaf Numbers - Recursive.py"}]}],"sources":["solutions"]},"topic-superpalindromes":{"key":"topic-superpalindromes","number":null,"title":"Super Palindromes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Super Palindromes.py","code":"class Solution:\n    def superpalindromesInRange(self, left: str, right: str) -> int:\n        L, R, MAGIC = int(left), int(right), 100000\n        def reverse(x):\n            ans = 0\n            while x:\n                ans = 10 * ans + x % 10\n                x = x // 10\n            return ans\n        def isPalindrome(x):\n            return x == reverse(x)\n        result = 0\n        for k in range(MAGIC):\n            s = str(k)\n            v = int(s + s[-2::-1]) ** 2\n            if v > R:\n                break\n            if v >= L and isPalindrome(v):\n                result += 1\n        for k in range(MAGIC):\n            s = str(k)\n            v = int(s + s[::-1]) ** 2\n            if v > R:\n                break\n            if v >= L and isPalindrome(v):\n                result += 1\n        return result","hash":"d59a6221ee596e36103ae848ed62d10494d716805a7435078192553662e4c8ac","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/Super Palindromes.py"}]}],"sources":["solutions"]},"topic-superpow":{"key":"topic-superpow","number":null,"title":"Super Pow","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Super Pow.py","code":"class Solution:\n    def superPow(self, a: int, b: List[int]) -> int:\n        result, mod = 1, 1337\n        a %= mod\n        for num in b:\n            result = (((result ** 10) % mod) * ((a ** num) % mod)) % mod\n        return result","hash":"a435442dc0ed77eace0accc6f33458aba804e908358bef312dbd3228c97ab3bd","origins":[{"source":"solutions","path":"Super Pow.py"}]}],"sources":["solutions"]},"topic-surfaceareaof3dshapes":{"key":"topic-surfaceareaof3dshapes","number":null,"title":"Surface Area of 3D Shapes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Surface Area of 3D Shapes.py","code":"class Solution:\n    def surfaceArea(self, grid: List[List[int]]) -> int:\n        result, n = 0, len(grid)\n        for i in range(n):\n            for j in range(n):\n                if grid[i][j]:\n                    result += 2\n                    for r, c in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):\n                        if 0 <= r < n and 0 <= c < n:\n                            val = grid[r][c]\n                        else:\n                            val = 0\n                        result += max(grid[i][j] - val, 0)\n        return result","hash":"362ea639677755da24b68f0e728a489970ed6df3e94dd77f94061d5a879c568f","origins":[{"source":"solutions","path":"Surface Area of 3D Shapes.py"}]}],"sources":["solutions"]},"topic-swapadjacentinlrstring":{"key":"topic-swapadjacentinlrstring","number":null,"title":"Swap Adjacent in LR String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Swap Adjacent in LR String.py","code":"class Solution:\n    def canTransform(self, start: str, end: str) -> bool:\n        if len(start) != len(end):\n            return False\n        if start.count('X') != end.count('X'):\n            return False\n        if start.replace('X', '') != end.replace('X', ''):\n            return False\n        i, j, n = 0, 0, len(start)\n        while i < n and j < n:\n            while i < n and start[i] == 'X':\n                i += 1\n            while j < n and end[j] == 'X':\n                j += 1\n            if i == n or j == n:\n                return i == n and j == n\n            if start[i] != end[j]:\n                return False\n            if start[i] == 'L' and i < j:\n                return False\n            if start[i] == 'R' and i > j:\n                return False\n            i += 1\n            j += 1\n        return True","hash":"e970c0a919d9ebd9c858c4e52ca771876e5647618776c0299da51a762316931e","origins":[{"source":"solutions","path":"Google Interview Questions/Swap Adjacent in LR String.py"}]}],"sources":["solutions"]},"topic-swapnodesinpairsiterative":{"key":"topic-swapnodesinpairsiterative","number":null,"title":"Swap Nodes in Pairs Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Swap Nodes in Pairs - Iterative.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def swapPairs(self, head: ListNode) -> ListNode:\n        dummyHead = ListNode(0)\n        dummyHead.next = head\n        prevNode = dummyHead\n        currentNode = dummyHead.next\n        while currentNode and currentNode.next:\n            firstNode = currentNode\n            secondNode = currentNode.next\n            prevNode.next = secondNode\n            firstNode.next = secondNode.next\n            secondNode.next = firstNode\n            prevNode = firstNode\n            currentNode = firstNode.next\n        return dummyHead.next","hash":"d2ba0614588ab7b15deed46b379dc10c24db0d22b55a8ba6b1a7faa0e8810eac","origins":[{"source":"solutions","path":"Recursion I/Swap Nodes in Pairs - Iterative.py"}]}],"sources":["solutions"]},"topic-swapnodesinpairsrecursive":{"key":"topic-swapnodesinpairsrecursive","number":null,"title":"Swap Nodes in Pairs Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Swap Nodes in Pairs - Recursive.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def swapPairs(self, head: ListNode) -> ListNode:\n        if head is None or head.next is None:\n            return head\n        firstNode = head\n        secondNode = head.next\n        firstNode.next = self.swapPairs(secondNode.next)\n        secondNode.next = firstNode\n        return secondNode","hash":"c13d57588d09e851ae814932c3b5c78b1608478abb85c9bc4fbec001dc825ccf","origins":[{"source":"solutions","path":"Recursion I/Swap Nodes in Pairs - Recursive.py"}]}],"sources":["solutions"]},"topic-symmetrictreeiterative":{"key":"topic-symmetrictreeiterative","number":null,"title":"Symmetric Tree Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Symmetric Tree - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isSymmetric(self, root: TreeNode) -> bool:\n        queue = deque([root, root])\n        while queue:\n            node1 = queue.popleft()\n            node2 = queue.popleft()\n            if node1 is None and node2 is None:\n                continue\n            if node1 is None or node2 is None:\n                return False\n            if node1.val != node2.val:\n                return False\n            queue.append(node1.left)\n            queue.append(node2.right)\n            queue.append(node1.right)\n            queue.append(node2.left)\n        return True","hash":"3a8274e437f9ae00e523a04633d58bf0879ff0f5de37c8391b170c7290f708a1","origins":[{"source":"solutions","path":"Binary Tree/Symmetric Tree - Iterative.py"}]}],"sources":["solutions"]},"topic-symmetrictreerecursive":{"key":"topic-symmetrictreerecursive","number":null,"title":"Symmetric Tree Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Symmetric Tree - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isSymmetric(self, root: TreeNode) -> bool:\n        def isMirror(node1, node2):\n            if node1 is None and node2 is None:\n                return True\n            if node1 is None or node2 is None:\n                return False\n            return node1.val == node2.val and isMirror(node1.right, node2.left) and isMirror(node1.left, node2.right)\n        return isMirror(root, root)","hash":"a3456c05e11e07c8d87ed93290f9aa8321dbe28ef33b6c2cf5255aac4b16fe9e","origins":[{"source":"solutions","path":"Binary Tree/Symmetric Tree - Recursive.py"}]}],"sources":["solutions"]},"topic-targetsum":{"key":"topic-targetsum","number":null,"title":"Target Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Target Sum.py","code":"class Solution:\n    def findTargetSumWays(self, nums: List[int], S: int) -> int:\n        dp = [0] * 2001\n        dp[nums[0] + 1000] += 1\n        dp[-nums[0] + 1000] += 1\n        for num in nums[1:]:\n            nextDP = [0] * 2001\n            for s in range(-1000, 1001):\n                if dp[s + 1000] > 0:\n                    nextDP[s + num + 1000] += dp[s + 1000]\n                    nextDP[s - num + 1000] += dp[s + 1000]\n            dp = nextDP\n        return 0 if S > 1000 else dp[S + 1000]","hash":"87ff65140c4ad0ea067039c66e454e32e8bdd15816f1574ba7333ff02acb3960","origins":[{"source":"solutions","path":"Stacks and Queues/Target Sum.py"}]}],"sources":["solutions"]},"topic-taskscheduler":{"key":"topic-taskscheduler","number":null,"title":"Task Scheduler","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Task Scheduler.py","code":"class Solution:\n    def leastInterval(self, tasks: List[str], n: int) -> int:\n        taskFrequency = [0] * 26\n        for task in tasks:\n            taskFrequency[ord(task) - ord('A')] += 1\n        taskFrequency = [i for i in taskFrequency if i > 0]\n        taskFrequency.sort()\n        maxFrequency = taskFrequency.pop()\n        idleTime = (maxFrequency - 1) * n\n        while taskFrequency and idleTime > 0:\n            idleTime -= min(maxFrequency - 1, taskFrequency.pop())\n        idleTime = max(0, idleTime)\n        return len(tasks) + idleTime","hash":"24b3ef5f5df1ca944aaa72dcd99385955f241cb0ba1a3bc8a0c818eca6c6c6ea","origins":[{"source":"solutions","path":"Task Scheduler.py"}]}],"sources":["solutions"]},"topic-techniques":{"key":"topic-techniques","number":null,"title":"techniques","difficulty":"Unknown","tags":[],"documents":[{"source":"primer","path":"docs/techniques.md","text":"# Basic Algorithmic Techniques\n\nThe following section discusses and analyses some of the most common algorithmic techniques and insights on how to solve technical problems. Many problems will reference this sections for quick navigation and convenience.\n\n## Techniques\n\n### 1. Read the problem statement aloud, making use of notes.\n\nWhen addressing a new problem, make sure you read the problem as thoroughly as possible so that your mind can expose logical errors. LeetCode allows you to add notes next to each problem so it makes it handy to jot down your thoughts and verify them once you attempting to write the solution.\n\n### 2. Consider Trading Time with Space.\n\nWhen you have a problem with bad time complexity (by doing multiple passes on the same data structure), then consider using fast access data structure like a HashTable to store intermediate results for later.\nThis may increase the Space Complexity of the algorithm but may reduce the time complexity as you merely have to search the Cache in $O(1)$ time instead of $O(n)$ time.\n\n### 3. Understand the basics of iteration.\n\nA lot of problems require understanding on how to iterate over data structures. The following examples show how to do this:\n\n- Iterate over a list:\n    ```js title=\"List iteration\"\n    const items = [1,2,3,4,5];\n    for (let i=0; i<items.length; i+=1) {\n        // access each item using items[i]\n    }\n    for (let item of items) {\n        // access each item directly using item\n    }\n    ```\n\n- Iterate over a linked list:\n    ```js title=\"List iteration\"\n    const ll = new LinkedList();\n    // init ll\n    while (ll) {\n        // navigate to the next element\n        ll = ll.next;\n    }\n    // ll is null here\n    ```\n- Iterate over a map key,value pairs:\n    ```js title=\"List iteration\"\n    const map = new Map();\n    // init map\n    for(let key of map.keys()) {\n        // iterate over each key\n    }\n    for(let val of map.value()) {\n        // iterate over each value\n    }\n    for(let entry of map.entries()) {\n        // iterate over each key, value using key=entry[0], value=entry[1]\n    }\n    ```\n\n### 4. Using two pointers to iterate over an array.\n\nA few problems work on arrays and require you to calculate a maximum or minimum value of something. One of the techniques that can be used is to have two pointers one one the start and one on the end of the array. For each loop iteration you either increment the start or decrement the end until the reach each-other. If you are operating on an array, try to use two pointers to see if you can find the solution by manipulating them until they cross each other.\n\n### 5. Using sorting to reduce complexity\n\nSorting is a quick and effortless way to reduce complexity of an expensive algorithm. This works especially good when you have `O(n^3)` or worse brute force variants of a solution. Sorting can also unlock the way to find the most optimal solution to many of the problems. If you are trying to figure out a solution, try to use sorting to see if that simplifies the problem any further.\n\n### 6. Using two pointers slow and fast for linked lists\n\nA few problems work on linked lists you are tasked to access a particular index of the linked list or attempt to detect cycles. One useful technique you want to use is to have two pointers traverse the list with different speeds (often one slow and one fast). This unlocks some interesting ways to solve problems related to linked lists."}],"solutions":[],"sources":["primer"]},"topic-teemoattacking":{"key":"topic-teemoattacking","number":null,"title":"Teemo Attacking","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Teemo Attacking.py","code":"class Solution:\n    def findPoisonedDuration(self, timeSeries: List[int], duration: int) -> int:\n        if len(timeSeries) == 0:\n            return 0\n        poisonedDuration = 0\n        for i in range(1, len(timeSeries)):\n            poisonedDuration += min(timeSeries[i] - timeSeries[i - 1], duration)\n        return poisonedDuration + duration","hash":"5205ab713ec0729d2b8286ad2ce7bd207b240174a41480af96fb84ac331354a8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Teemo Attacking.py"}]}],"sources":["solutions"]},"topic-thediningphilosophers":{"key":"topic-thediningphilosophers","number":null,"title":"The Dining Philosophers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"The Dining Philosophers.py","code":"from threading import Lock\n\nclass DiningPhilosophers:\n    def __init__(self):\n        self.forks = [Lock() for _ in range(5)]\n\n    # call the functions directly to execute, for example, eat()\n    def wantsToEat(self,\n                   philosopher: int,\n                   pickLeftFork: 'Callable[[], None]',\n                   pickRightFork: 'Callable[[], None]',\n                   eat: 'Callable[[], None]',\n                   putLeftFork: 'Callable[[], None]',\n                   putRightFork: 'Callable[[], None]') -> None:\n        # To avoid deadlock philosopher at even places would try to acquire right fork first, rest would try to acquire left fork first\n        if philosopher % 2 == 0:\n            leftForkIndex, rightForkIndex = (philosopher + 1) % 5, (philosopher) % 5 \n        else:\n            leftForkIndex, rightForkIndex = (philosopher) % 5, (philosopher + 1) % 5\n        self.forks[leftForkIndex].acquire()\n        self.forks[rightForkIndex].acquire()\n        pickLeftFork()\n        pickRightFork()\n        eat()\n        putLeftFork()\n        putRightFork()\n        self.forks[leftForkIndex].release()\n        self.forks[rightForkIndex].release()","hash":"9ccbb0a2f847389b8c06e900bf21c3d9beb99985796702202f5048a049b93ad2","origins":[{"source":"solutions","path":"The Dining Philosophers.py"}]}],"sources":["solutions"]},"topic-thekweakestrowsinamatrix":{"key":"topic-thekweakestrowsinamatrix","number":null,"title":"The K Weakest Rows in a Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"The K Weakest Rows in a Matrix.py","code":"class Solution:\n    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:\n        result, soldierFreq = [], []\n        for index, row in enumerate(mat):\n            soldierFreq.append((row.count(1), index))\n        soldierFreq.sort()\n        return [i for freq, i in soldierFreq[:k]]","hash":"bc9b798f4eeff6aa78f63ecf9a617cee902eba150bdcf1c4c7f84adb348058ef","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/The K Weakest Rows in a Matrix.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/The K Weakest Rows in a Matrix.py"}]}],"sources":["solutions"]},"topic-thekthfactorofn":{"key":"topic-thekthfactorofn","number":null,"title":"The kth Factor of n","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"The kth Factor of n.py","code":"class Solution:\n    def kthFactor(self, n: int, k: int) -> int:\n        divisors, sqrt = [], int(n ** 0.5)\n        for i in range(1, sqrt + 1):\n            if n % i == 0:\n                k -= 1\n                divisors.append(i)\n                if k == 0:\n                    return i\n        if sqrt * sqrt == n:\n            k += 1\n        numberOfDivisors = len(divisors)\n        return n // divisors[numberOfDivisors - k] if k <= numberOfDivisors else -1","hash":"87743d08ea6e8a04207832fd8548b12ed031816b360de8f47eadd94102cd0c8c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/The kth Factor of n.py"}]}],"sources":["solutions"]},"topic-thirdmaximumnumber":{"key":"topic-thirdmaximumnumber","number":null,"title":"Third Maximum Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Third Maximum Number.py","code":"class Solution:\n    def thirdMax(self, nums: List[int]) -> int:\n        maximums = set()\n        for num in nums:\n            maximums.add(num)\n            if len(maximums) > 3:\n                maximums.remove(min(maximums))\n        if len(maximums) == 3:\n            return min(maximums)\n        return max(maximums)","hash":"6ba5bf219bc0c8155e098ddfc385ee9c7dc2bb5d4d7a2c44b89d26963f1cf402","origins":[{"source":"solutions","path":"Arrays/Third Maximum Number.py"}]}],"sources":["solutions"]},"topic-thousandseparator":{"key":"topic-thousandseparator","number":null,"title":"Thousand Separator","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Thousand Separator.py","code":"class Solution:\n    def thousandSeparator(self, n: int) -> str:\n        return '.'.join(f'{n:,}'.split(','))","hash":"3174e33521b6cca48e1e162da8fb232c261ce1dd9670852be02f8b6b094f795c","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 33/Thousand Separator.py"}]}],"sources":["solutions"]},"topic-threeconsecutiveodds":{"key":"topic-threeconsecutiveodds","number":null,"title":"Three Consecutive Odds","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Three Consecutive Odds.py","code":"class Solution:\n    def threeConsecutiveOdds(self, arr: List[int]) -> bool:\n        numberOfOdds = 0\n        for num in arr:\n            if num % 2:\n                numberOfOdds += 1\n            else:\n                numberOfOdds = 0\n            if numberOfOdds >= 3:\n                return True\n        return False","hash":"bf9633e0c9eaa3378b6a6b8994e7f4b227a24287bdeb46070d8bc9d74b66fdca","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 202/Three Consecutive Odds.py"}]}],"sources":["solutions"]},"topic-threeequalparts":{"key":"topic-threeequalparts","number":null,"title":"Three Equal Parts","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Three Equal Parts.py","code":"class Solution:\n    def threeEqualParts(self, A: List[int]) -> List[int]:\n        IMPOSSIBLE, S = [-1, -1], sum(A)\n        if S % 3:\n            return IMPOSSIBLE\n        T = S // 3\n        if T == 0:\n            return [0, len(A) - 1]\n        breaks, currentSum = [], 0\n        for i, digit in enumerate(A):\n            if digit:\n                currentSum += digit\n                if currentSum in {1, T + 1, 2 * T + 1}:\n                    breaks.append(i)\n                if currentSum in {T, 2 * T, 3 * T}:\n                    breaks.append(i)\n        i1, j1, i2, j2, i3, j3 = breaks\n        # The array is in the form W [i1, j1] X [i2, j2] Y [i3, j3] Z where [i1, j1] is a block of 1s, etc.\n        if not(A[i1 : j1 + 1] == A[i2 : j2 + 1] == A[i3 : j3 + 1]):\n            return IMPOSSIBLE\n        # x, y, z: the number of zeros after part 1, 2, 3\n        x, y, z = i2 - j1 - 1, i3 - j2 - 1, len(A) - j3 - 1\n        if x < z or y < z:\n            return IMPOSSIBLE\n        j1, j2 = j1 + z, j2 + z\n        return [j1, j2 + 1]","hash":"58aff41d9fadf8aa23908569b7b11966fbf187de03437b24d7601141136c00ff","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Three Equal Parts.py"}]}],"sources":["solutions"]},"topic-throneinheritance":{"key":"topic-throneinheritance","number":null,"title":"Throne Inheritance","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Throne Inheritance.py","code":"class ThroneInheritance:\n\n    def __init__(self, kingName: str):\n        self.inheritance = defaultdict(list)\n        self.kingName = kingName\n        self.dead = set()\n\n    def birth(self, parentName: str, childName: str) -> None:\n        self.inheritance[parentName].append(childName)\n\n    def death(self, name: str) -> None:\n        self.dead.add(name)\n\n    def getInheritanceOrder(self) -> List[str]:\n        result = []\n        def dfs(name):\n            nonlocal result\n            if name not in self.dead:\n                result.append(name)\n            for child in self.inheritance[name]:\n                dfs(child)\n        dfs(self.kingName)\n        return result\n\n\n# Your ThroneInheritance object will be instantiated and called as such:\n# obj = ThroneInheritance(kingName)\n# obj.birth(parentName,childName)\n# obj.death(name)\n# param_3 = obj.getInheritanceOrder()","hash":"14a13799e01ce6c16aa319eceb3500227cc437fa449b2fb72592caae15060554","origins":[{"source":"solutions","path":"Throne Inheritance.py"}]},{"language":"python","name":"Throne Inheritance.py","code":"class ThroneInheritance:\n\n    def __init__(self, kingName: str):\n        self.king = kingName\n        self.dead = set()\n        self.graph = defaultdict(list)\n\n    def birth(self, parentName: str, childName: str) -> None:\n        self.graph[parentName].append(childName)\n\n    def death(self, name: str) -> None:\n        self.dead.add(name)\n\n    def getInheritanceOrder(self) -> List[str]:\n        result = []\n        def dfs(node):\n            if node not in self.dead:\n                result.append(node)\n            for child in self.graph[node]:\n                dfs(child)\n        dfs(self.king)\n        return result\n\n\n# Your ThroneInheritance object will be instantiated and called as such:\n# obj = ThroneInheritance(kingName)\n# obj.birth(parentName,childName)\n# obj.death(name)\n# param_3 = obj.getInheritanceOrder()","hash":"260baac04b24c5dbb610f53dd8f3566d10c97b3d8dc4a61c3a86219dd603d6c0","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 208/Throne Inheritance.py"}]}],"sources":["solutions"]},"topic-timeneededtobuytickets":{"key":"topic-timeneededtobuytickets","number":null,"title":"Time Needed to Buy Tickets","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Time Needed to Buy Tickets.py","code":"class Solution:\n    def timeRequiredToBuy(self, tickets: List[int], k: int) -> int:\n        total = 0\n        for index, t in enumerate(tickets):\n            if index <= k:\n                total += min(t, tickets[k])\n            else:\n                total += min(t, tickets[k] - 1)\n        return total","hash":"e665dcf931b7f1215fc1a068f54ad65647de8b98cf6a7df668918aa5baa6d352","origins":[{"source":"solutions","path":"Time Needed to Buy Tickets.py"}]}],"sources":["solutions"]}});
